/** Show percent-encoded Hebrew addresses as readable text. */
function readableUrls(text:string){return String(text||'').replace(/https?:\/\/\S+/g,u=>{try{return decodeURI(u);}catch{return u;}});}
function siteHost(url:string){try{return new URL(url).host.replace(/^www\./,'');}catch{return url;}}
function ArticleProgress({status,administrative=false}:{status:string;administrative?:boolean}) {
    const step=administrative?(['published','demo_completed'].includes(status)?4:status==='sent'?3:['admin_review','approved'].includes(status)?2:1):status==='published'||status==='demo_completed'?3:['admin_review','approved','sent'].includes(status)?2:1;
    const first=({writing:'בכתיבה',revisions:'הוחזרה לתיקון',scheduled:'שליחה מתוזמנת',cancelled:'בוטלה'} as Record<string,string>)[status]||'עריכה';
    const labels=administrative?[first,status==='admin_review'?'ממתינה לאישור':status==='approved'?'אושרה':'אישור מנהל','אצל הספק',status==='demo_completed'?'הדגמה הושלמה':'פורסמה']:['עריכת הכתבה','נשלח לפרסום','פורסם'];
    return <ol className="studio-progress" aria-label="שלבי הכתבה">{labels.map((label,i)=><li key={i} aria-current={step===i+1?'step':undefined} className={step===i+1?'current':step>i+1?'complete':''}><span>{step>i+1?<Check size={17}/>:i+1}</span><b>{label}</b></li>)}</ol>;
}
