type Picture={id:string;credit:string;creditUrl:string;alt:string;primary?:boolean;token?:string};
function StudioField({label,children}:{label:string;children:React.ReactNode}) {return <label className="grid min-w-0 gap-2 text-base font-semibold text-slate-800">{label}{children}</label>;}
function pictureMarkup(p:Picture) {const figure=document.createElement('figure');figure.contentEditable='false';const img=document.createElement('img');img.src='/api/files/'+p.id;img.alt=p.alt||'תמונה במאמר';img.setAttribute('data-credit',p.credit.trim());const caption=document.createElement('figcaption');caption.textContent=p.credit.trim();figure.appendChild(img);figure.appendChild(caption);return figure;}
/** An imported Word file's first heading becomes the article title; drop that same heading from the body so it is not shown twice. */
function stripLeadingTitle(html:string,title:string){
    const wanted=title.replace(/\s+/g,' ').trim();if(!wanted||typeof DOMParser==='undefined')return html;
    const doc=new DOMParser().parseFromString('<div>'+html+'</div>','text/html'),root=doc.body.firstElementChild;if(!root)return html;
    for(const el of Array.from(root.children)){const text=(el.textContent||'').replace(/\s+/g,' ').trim();if(!text&&!el.querySelector('img'))continue;if(text===wanted&&/^(H[1-6]|P)$/.test(el.tagName))el.remove();break;}
    return root.innerHTML;
}
function eventNote(event:Row){try{return (typeof event.data==='string'?JSON.parse(event.data):event.data)?.note||'';}catch{return '';}}

